class Solution {
public:
    int longestAwesome(string s) {
        int seen[1024];
        for (int i = 0; i < 1024; ++i) seen[i] = -2;
        seen[0] = -1;

        int mask = 0, ans = 0;
        int n = (int)s.size();

        for (int i = 0; i < n; ++i) {
            mask ^= (1 << (s[i] - '0'));

            if (seen[mask] != -2) {
                int len = i - seen[mask];
                if (len > ans) ans = len;
            }

            for (int d = 0; d < 10; ++d) {
                int want = mask ^ (1 << d);
                if (seen[want] != -2) {
                    int len = i - seen[want];
                    if (len > ans) ans = len;
                }
            }

            if (seen[mask] == -2) seen[mask] = i;
        }

        return ans;
    }
};
